n=A.amT(B.b2.ck(0,'{\n    "questionDetailsPaginated": {\n        "docs": [\n            {\n                "_id": "6a2fc40fc40ebece41165d59",\n                "s_no": 21,\n                "text": {\n                    "EN": "<div class=\\"cell-rich\\" data-col=\\"question_text\\"><div data-col=\\"question_text\\"><p>If the project\'s Earned Value (EV) is $100,000 and the Actual Costs (AC) spent is $95,000, what is the Cost Variance (CV) of the project?</p></div></div>"\n                },\n                "question_image": null,\n                "options": [\n                    {\n                        "id": "A",\n                        "text": {\n                            "EN": "The cost variance is $0.95"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "B",\n                        "text": {\n                            "EN": "The cost variance is $1.05"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "C",\n                        "text": {\n                            "EN": "The cost variance is-$5,000"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "D",\n                        "text": {\n                            "EN": "The cost variance is $5,000"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "E",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "F",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "G",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "H",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "I",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    }\n                ],\n                "correct_answer_id": "D",\n                "marks_per_question": 1,\n                "minus_marks_per_question": 0.5,\n                "explanation_in_english": "<div class=\\"cell-rich\\" data-col=\\"explanation\\"><p>Cost Variance (CV) = EV-AC<br>CV = $100,000-$95,000<br>CV = $<b>5,000</b></p></div>",\n                "explanation_image": null,\n                "active": true,\n                "is_error": false,\n                "train": [],\n                "flip_back": [\n                    "<div><p>Cost Variance = Earned Value-Actual Costs</p><p>(CV = EV-AC)</p></div>"\n                ],\n                "flip_front": [\n                    "<div><p>What is the formula for Cost Variance?</p></div>"\n                ],\n                "error": [],\n                "__v": 0,\n                "createdAt": "2026-06-15T09:21:19.357Z",\n                "updatedAt": "2026-06-15T09:21:19.357Z",\n                "id": "6a2fc40fc40ebece41165d59"\n            },\n            {\n                "_id": "6a2fc40fc40ebece41165d5a",\n                "s_no": 22,\n                "text": {\n                    "EN": "<div class=\\"cell-rich\\" data-col=\\"question_text\\"><div data-col=\\"question_text\\"><p>A large scope change was approved. You thus should update <i>which</i> project documents? Select <b>three</b>.</p></div></div>"\n                },\n                "question_image": null,\n                "options": [\n                    {\n                        "id": "A",\n                        "text": {\n                            "EN": "The Scope Baseline"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "B",\n                        "text": {\n                            "EN": "Requirements documentation"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "C",\n                        "text": {\n                            "EN": "The WBS dictionary"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "D",\n                        "text": {\n                            "EN": "The Project Charter"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "E",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "F",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "G",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "H",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "I",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    }\n                ],\n                "correct_answer_id": "A, B, C",\n                "marks_per_question": 1,\n                "minus_marks_per_question": 0.5,\n                "explanation_in_english": "<div class=\\"cell-rich\\" data-col=\\"explanation\\"><p>The <i>scope</i> has changed: update the Scope Baseline from the current time forward.<br><i>Requirements</i> have changed and should be updated.<br>The Work Breakdown Structure dictionary is updated per the <i>changed deliverables</i> and <i>schedule</i>.<br><b>Key Point</b>: The Scope Baseline, Requirements documentation, and WBS Dictionary must be updated for large changes.<br>The Project Charter contains high level requirements that need not be changed for most Change Requests.</p></div>",\n                "explanation_image": null,\n                "active": true,\n                "is_error": false,\n                "train": [\n                    "<div><div><p style=\\"margin:0; padding:0;\\">A <b>Work Breakdown Structure dictionary</b> provides additional information about the elements within a WBS; offering <i>descriptions</i> of tasks, deliverables, and responsibilities associated with each component. Specifically, it helps define activities and milestones, identifies deliverables, and assigns accountability for tasks, ensuring clarity and alignment with the project\'s scope. This facilitates project management by dissecting the scope into smaller, manageable elements or projects.</p></div></div>"\n                ],\n                "flip_back": [],\n                "flip_front": [],\n                "error": [],\n                "__v": 0,\n                "createdAt": "2026-06-15T09:21:19.358Z",\n                "updatedAt": "2026-06-15T09:21:19.358Z",\n                "id": "6a2fc40fc40ebece41165d5a"\n            },\n            {\n                "_id": "6a2fc40fc40ebece41165d5b",\n                "s_no": 23,\n                "text": {\n                    "EN": "<div class=\\"cell-rich\\" data-col=\\"question_text\\"><div data-col=\\"question_text\\"><p>Your project team experienced in Waterfall has been assigned their first Agile project. To assist the transition, they are keeping some Waterfall elements in place. During the iteration review, it was realized that a misunderstanding among team member led to a duplication of efforts. What do you do?</p></div></div>"\n                },\n                "question_image": null,\n                "options": [\n                    {\n                        "id": "A",\n                        "text": {\n                            "EN": "Bring up the topic in the iteration retrospective"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "B",\n                        "text": {\n                            "EN": "Do little since the team is still transitioning"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "C",\n                        "text": {\n                            "EN": "Fallback to a Waterfall project management framework"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "D",\n                        "text": {\n                            "EN": "Submit a change request to update the Communication Management Plan"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "E",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "F",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "G",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "H",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "I",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    }\n                ],\n                "correct_answer_id": "A",\n                "marks_per_question": 1,\n                "minus_marks_per_question": 0.5,\n                "explanation_in_english": "<div class=\\"cell-rich\\" data-col=\\"explanation\\"><p>Use the iteration retrospective to address the issue. Retrospectives help teams learn from past work and improve processes, which is beneficial in both Agile and hybrid projects.</p></div>",\n                "explanation_image": null,\n                "active": true,\n                "is_error": false,\n                "train": [\n                    "<div><div><p style=\\"margin:0; padding:0;\\">The <b>Iteration Retrospective</b> and <b>Sprint Review</b> differ:</p><ul style=\\"list-style:none; margin:0; padding:0;\\"><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\"><b>Sprint Review</b>: Focuses on reviewing the work completed during the Sprint, showcasing deliverables to stakeholders, and gathering feedback on the product. It is product-focused and involves external participants.</div></div></li></ul><ul style=\\"list-style:none; margin:0; padding:0;\\"><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\"><b>Iteration Retrospective</b>: Focuses on evaluating team processes, identifying improvements, and fostering better collaboration. It is team-focused and internal.</div></div></li></ul><p style=\\"margin:0; padding:0;\\">These meetings serve distinct purposes within Agile frameworks.</p></div></div>"\n                ],\n                "flip_back": [],\n                "flip_front": [],\n                "error": [],\n                "__v": 0,\n                "createdAt": "2026-06-15T09:21:19.358Z",\n                "updatedAt": "2026-06-15T09:21:19.358Z",\n                "id": "6a2fc40fc40ebece41165d5b"\n            },\n            {\n                "_id": "6a2fc40fc40ebece41165d5c",\n                "s_no": 24,\n                "text": {\n                    "EN": "<div class=\\"cell-rich\\" data-col=\\"question_text\\"><div data-col=\\"question_text\\"><p>A company must choose between two projects.<br>Both projects take 12 months and cost $250,000. The decision is based on a 3-year forecast, post-delivery.<br>Project 1 optimizes processes, saving $300,000 annually starting the first year after completion.<br>Project 2 develops a new product, generating income during and after the project: $15,000 in the first 6 months, $55,000 in the next 6 months, $230,000 in the first year after completion, and $300,000 in each of the next two years. Which project offers more financial value?</p></div></div>"\n                },\n                "question_image": null,\n                "options": [\n                    {\n                        "id": "A",\n                        "text": {\n                            "EN": "Both projects are equally attractive"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "B",\n                        "text": {\n                            "EN": "One cannot say based on the numbers"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "C",\n                        "text": {\n                            "EN": "The first project is more attractive"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "D",\n                        "text": {\n                            "EN": "The second project is more attractive"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "E",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "F",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "G",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "H",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "I",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    }\n                ],\n                "correct_answer_id": "D",\n                "marks_per_question": 1,\n                "minus_marks_per_question": 0.5,\n                "explanation_in_english": "<div class=\\"cell-rich\\" data-col=\\"explanation\\"><p>The financial value is equal for both projects, but <b>the second project starts generating income earlier</b> (during the project itself), which can be advantageous for cash flow.<br>Care for the math?:<br>To determine which project offers more financial value, calculate the&nbsp;<b>Net Cash Flow</b>&nbsp;over the 3-year period post-delivery for each project. Here\'s the breakdown:<br><b>Project 1 (Process Optimization):</b></p><div><ul style=\\"list-style:none; margin:0; padding:0;\\"><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\"><b>Financial Impact:</b>&nbsp;Saves $300,000 annually post-delivery.</div></div></li><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\"><b>Cost:</b>&nbsp;$250,000.</div></div></li></ul></div><p><b>Cash Flow:</b></p><div><ul style=\\"list-style:none; margin:0; padding:0;\\"><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\">During project (Year 0): Spend $250,000.</div></div></li><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\">Year 1 saving: +$300,000.</div></div></li><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\">Year 2 saving: +$300,000.</div></div></li><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\">Year 3 saving: +$300,000.</div></div></li></ul></div><p><b>Total Cash Flow:</b></p><div><ul style=\\"list-style:none; margin:0; padding:0;\\"><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\">Cumulative Cash Flow over 4 years (Year 0 to Year 3):<div class=\\"nb-detected-continuation\\"><b>-$250,000 + $300,000 + $300,000 + $300,000 = $650,000.</b></div></div></div></li></ul></div><p><br><b>Project 2 (New Product Development):</b></p><div><ul style=\\"list-style:none; margin:0; padding:0;\\"><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\"><b>Financial Impact:</b>&nbsp;Generates income during and after project completion.</div></div></li><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\"><b>Cost:</b>&nbsp;$250,000.</div></div></li></ul></div><p><b>Cash Flow:</b></p><div><ul style=\\"list-style:none; margin:0; padding:0;\\"><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\">During project (Year 0):<ul style=\\"list-style:none; margin:0; padding:0;\\"><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u25e6</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\">First 6 months: +$15,000.</div></div></li><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u25e6</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\">Next 6 months: +$55,000.<div class=\\"nb-detected-continuation\\"><b>Net Year 0 (project year) flow:-$250,000 + $15,000 + $55,000 =-$180,000.</b></div></div></div></li></ul></div></div></li></ul></div><div><ul style=\\"list-style:none; margin:0; padding:0;\\"><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\">Year 1 post-completion: +$230,000.</div></div></li><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\">Year 2 post-completion: +$300,000.</div></div></li><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\">Year 3 post-completion: +$300,000.</div></div></li></ul></div><p><b>Total Cash Flow:</b></p><div><ul style=\\"list-style:none; margin:0; padding:0;\\"><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\">Cumulative Cash Flow over 4 years (Year 0 to Year 3):<div class=\\"nb-detected-continuation\\"><b>-$250,000 + $15,000 + $55,000 + $230,000 + $300,000 + $300,000 = $650,000.</b></div></div></div></li></ul></div><p><br><b>Comparison:</b><br>Both projects yield the same 3-year net cash flow:&nbsp;<b>$650,000.</b><br>However, the choice may depend on&nbsp;<b>risk tolerance</b>:</p><div><ul style=\\"list-style:none; margin:0; padding:0;\\"><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\"><b>Project 1</b>&nbsp;offers a steady and predictable annual savings.</div></div></li><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\"><b>Project 2</b>&nbsp;carries potential market risk (since product income depends on sales and market adoption) but also allows early returns during the project phase.</div></div></li></ul></div></div>",\n                "explanation_image": null,\n                "active": true,\n                "is_error": false,\n                "train": [],\n                "flip_back": [],\n                "flip_front": [],\n                "error": [],\n                "__v": 0,\n                "createdAt": "2026-06-15T09:21:19.359Z",\n                "updatedAt": "2026-06-15T09:21:19.359Z",\n                "id": "6a2fc40fc40ebece41165d5c"\n            },\n            {\n                "_id": "6a2fc40fc40ebece41165d5d",\n                "s_no": 25,\n                "text": {\n                    "EN": "<div class=\\"cell-rich\\" data-col=\\"question_text\\"><div data-col=\\"question_text\\"><p>Activity 1 has a duration of 20 days, activity 2 of 10 days, activity 3 of 5 days and activity 4 of 6 days. What is the minimum duration between milestones A and B?</p><br><p><img data-img-index=\\"0\\" data-original-mime=\\"image/png\\" src=\\"https://pmpep.s3.amazonaws.com/file_1781515275525.webp\\" style=\\"width:576px; height:255px;\\"></p></div><div data-col=\\"question_text_2\\"><p>What is the minimum total duration between milestones A and B if Activity 1 takes 20 days, Activity 2 takes 10 days, Activity 3 takes 5 days, and Activity 4 takes 6 days?</p></div></div>"\n                },\n                "question_image": null,\n                "options": [\n                    {\n                        "id": "A",\n                        "text": {\n                            "EN": "36 days"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "B",\n                        "text": {\n                            "EN": "37 days"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "C",\n                        "text": {\n                            "EN": "39 days"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "D",\n                        "text": {\n                            "EN": "42 days"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "E",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "F",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "G",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "H",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "I",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    }\n                ],\n                "correct_answer_id": "A",\n                "marks_per_question": 1,\n                "minus_marks_per_question": 0.5,\n                "explanation_in_english": "<div class=\\"cell-rich\\" data-col=\\"explanation\\"><p>The critical path between milestones A and B involves Activity 1 (20 days), followed by Activity 2 (10 days), and then Activity 4 (6 days). The total duration is 20 + 10 + 6 = 36 days.</p></div>",\n                "explanation_image": null,\n                "active": true,\n                "is_error": false,\n                "train": [],\n                "flip_back": [],\n                "flip_front": [],\n                "error": [],\n                "__v": 0,\n                "createdAt": "2026-06-15T09:21:19.359Z",\n                "updatedAt": "2026-06-15T09:21:19.359Z",\n                "id": "6a2fc40fc40ebece41165d5d"\n            },\n            {\n                "_id": "6a2fc40fc40ebece41165d5e",\n                "s_no": 26,\n                "text": {\n                    "EN": "<div class=\\"cell-rich\\" data-col=\\"question_text\\"><div data-col=\\"question_text\\"><p>An organization with a rigid command-and-control structure wishes to implement Agile mindsets and methods. What should the organization do first to allow for the implementation?</p></div></div>"\n                },\n                "question_image": null,\n                "options": [\n                    {\n                        "id": "A",\n                        "text": {\n                            "EN": "Increase the frequency of inspections"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "B",\n                        "text": {\n                            "EN": "Increase the frequency of audits"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "C",\n                        "text": {\n                            "EN": "Create an environment of safety"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "D",\n                        "text": {\n                            "EN": "Initiate a Kanban board"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "E",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "F",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "G",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "H",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "I",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    }\n                ],\n                "correct_answer_id": "C",\n                "marks_per_question": 1,\n                "minus_marks_per_question": 0.5,\n                "explanation_in_english": "<div class=\\"cell-rich\\" data-col=\\"explanation\\"><p>To successfully implement any new methodology in an organization with a rigid command-and-control structure, the first step is to create an environment of psychological safety. This allows team members to collaborate, communicate openly, and make decisions without fear, which is essential for change.</p></div>",\n                "explanation_image": null,\n                "active": true,\n                "is_error": false,\n                "train": [\n                    "<div><div><p style=\\"margin:0; padding:0;\\">Various methodologies are used across industries for project management, process improvement, and software development. Key methodologies include:</p><ul style=\\"list-style:none; margin:0; padding:0;\\"><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\"><b>Agile</b>: A flexible, iterative approach focused on delivering solutions incrementally and fostering collaboration. Common frameworks include Scrum and Scaled Agile Framework</div></div></li><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\"><b>Lean Six Sigma</b>: Combines Lean principles (waste reduction) and Six Sigma (process improvement) to enhance efficiency and quality in projects. It uses phases like D-M-A-I-C (Define, Measure, Analyze, Improve, Control)</div></div></li><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\"><b>Capability Maturity Model Integration</b> (CMMI): A framework for improving organizational processes and performance, widely adopted for quality assurance and control</div></div></li><li style=\\"list-style:none; margin:0 0 4px 0; padding:0;\\"><div class=\\"bullet-item-grid\\" style=\\"display:grid;grid-template-columns:1.4em 1fr;column-gap:0.35em;align-items:start;\\"><div class=\\"bullet-marker\\" style=\\"display:block;text-align:right;line-height:1.4;\\">\u2022</div><div class=\\"bullet-body\\" style=\\"display:block;min-width:0;overflow-wrap:anywhere;word-break:break-word;\\"><b>Software Assurance</b>: Focuses on reducing vulnerabilities in software development through secure coding standards, testing, and operational analysis</div></div></li></ul><p style=\\"margin:0; padding:0;\\">These methodologies are tailored to meet specific organizational goals efficiently and in alignment with strategic objectives.</p></div></div>"\n                ],\n                "flip_back": [],\n                "flip_front": [],\n                "error": [],\n                "__v": 0,\n                "createdAt": "2026-06-15T09:21:19.359Z",\n                "updatedAt": "2026-06-15T09:21:19.359Z",\n                "id": "6a2fc40fc40ebece41165d5e"\n            },\n            {\n                "_id": "6a2fc40fc40ebece41165d5f",\n                "s_no": 27,\n                "text": {\n                    "EN": "<div class=\\"cell-rich\\" data-col=\\"question_text\\"><div data-col=\\"question_text\\"><p>Why is it important to document <b>assumptions</b> in a project?</p></div></div>"\n                },\n                "question_image": null,\n                "options": [\n                    {\n                        "id": "A",\n                        "text": {\n                            "EN": "Assumptions might later prove wrong. Knowing which assumptions were incorrect allows baseline adjustments in case of project crisis"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "B",\n                        "text": {\n                            "EN": "Assumptions recorded in the assumption log may help identify project risks and other kinds of uncertainties"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "C",\n                        "text": {\n                            "EN": "Assumptions limit the project management team\'s options because assumptions cannot be controlled"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "D",\n                        "text": {\n                            "EN": "In case of schedule or budget overruns, the documentation of assumptions supports a clear assignment of responsibility"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "E",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "F",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "G",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "H",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "I",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    }\n                ],\n                "correct_answer_id": "B",\n                "marks_per_question": 1,\n                "minus_marks_per_question": 0.5,\n                "explanation_in_english": "<div class=\\"cell-rich\\" data-col=\\"explanation\\"><p>Documenting assumptions helps identify risks and uncertainties. By recording them in an assumption log, the project team can better anticipate and manage risks, as these items when realized can impact the project scope, schedule, or budget.</p></div>",\n                "explanation_image": null,\n                "active": true,\n                "is_error": false,\n                "train": [],\n                "flip_back": [],\n                "flip_front": [],\n                "error": [],\n                "__v": 0,\n                "createdAt": "2026-06-15T09:21:19.359Z",\n                "updatedAt": "2026-06-15T09:21:19.359Z",\n                "id": "6a2fc40fc40ebece41165d5f"\n            },\n            {\n                "_id": "6a2fc40fc40ebece41165d60",\n                "s_no": 28,\n                "text": {\n                    "EN": "<div class=\\"cell-rich\\" data-col=\\"question_text\\"><div data-col=\\"question_text\\"><p>Your Scrum team asked whether it should use a Burnup chart or a Burndown chart. What is the difference between the two?</p></div></div>"\n                },\n                "question_image": null,\n                "options": [\n                    {\n                        "id": "A",\n                        "text": {\n                            "EN": "You can use neither of the two chart types to do variance analysis during a Sprint in Scrum"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "B",\n                        "text": {\n                            "EN": "Only burndown charts are appropriate to do variance analysis against a baseline during a Sprint"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "C",\n                        "text": {\n                            "EN": "A burndown chart reflects open work, a burnup chart reflects work performed"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "D",\n                        "text": {\n                            "EN": "A burndown chart reflects work performed, a burnup chart reflects open work"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "E",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "F",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "G",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "H",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "I",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    }\n                ],\n                "correct_answer_id": "C",\n                "marks_per_question": 1,\n                "minus_marks_per_question": 0.5,\n                "explanation_in_english": "<div class=\\"cell-rich\\" data-col=\\"explanation\\"><p><b>Burnup</b> <b>charts</b> show work completed and can illustrate scope changes. They can have two lines: one for total scope and one for work completed.<br><b>Burndown</b> <b>charts</b> track remaining work to help monitor planned work. They can have two lines: one for planned progress and one for actual progress.<br></p><table style=\\"border-collapse:collapse; border:1px solid #777; width:100%; table-layout:auto;\\"><tbody><tr><td style=\\"border:1px solid #777; padding:4px; word-wrap:break-word; vertical-align:top;\\"><div><p><img data-img-index=\\"0\\" data-original-mime=\\"image/png\\" src=\\"https://pmpep.s3.amazonaws.com/file_1781515275613.webp\\" style=\\"width:349px; height:238px;\\"></p><p><img data-img-index=\\"1\\" data-original-mime=\\"image/png\\" src=\\"https://pmpep.s3.amazonaws.com/file_1781515275690.webp\\" style=\\"width:353px; height:198px;\\"></p></div></td></tr></tbody></table></div>",\n                "explanation_image": null,\n                "active": true,\n                "is_error": false,\n                "train": [],\n                "flip_back": [],\n                "flip_front": [],\n                "error": [],\n                "__v": 0,\n                "createdAt": "2026-06-15T09:21:19.360Z",\n                "updatedAt": "2026-06-15T09:21:19.360Z",\n                "id": "6a2fc40fc40ebece41165d60"\n            },\n            {\n                "_id": "6a2fc40fc40ebece41165d61",\n                "s_no": 29,\n                "text": {\n                    "EN": "<div class=\\"cell-rich\\" data-col=\\"question_text\\"><div data-col=\\"question_text\\"><p>A project is managed by departments of an organization and expedited by a project coordinator. What is most likely true?</p></div></div>"\n                },\n                "question_image": null,\n                "options": [\n                    {\n                        "id": "A",\n                        "text": {\n                            "EN": "The project is performed in a weak to balanced matrix"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "B",\n                        "text": {\n                            "EN": "The performing organization is doing \\"management by projects\\""\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "C",\n                        "text": {\n                            "EN": "The project is performed in a strong matrix"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "D",\n                        "text": {\n                            "EN": "The performing organization is project-oriented"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "E",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "F",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "G",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "H",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "I",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    }\n                ],\n                "correct_answer_id": "A",\n                "marks_per_question": 1,\n                "minus_marks_per_question": 0.5,\n                "explanation_in_english": "<div class=\\"cell-rich\\" data-col=\\"explanation\\"><p>In a matrix organization, the project manager shares authority with functional managers.<br>There exist different types of matrix structures:<br>Weak Matrix, Balanced Matrix, and Strong Matrix.<br>In this case, the mention of a \\"project coordinator\\" suggests a weak matrix structure as a project manager has limited authority and the project is managed mainly by functional departments--which is characteristic of a weak matrix organization.</p></div>",\n                "explanation_image": null,\n                "active": true,\n                "is_error": false,\n                "train": [],\n                "flip_back": [],\n                "flip_front": [],\n                "error": [],\n                "__v": 0,\n                "createdAt": "2026-06-15T09:21:19.360Z",\n                "updatedAt": "2026-06-15T09:21:19.360Z",\n                "id": "6a2fc40fc40ebece41165d61"\n            },\n            {\n                "_id": "6a2fc40fc40ebece41165d62",\n                "s_no": 30,\n                "text": {\n                    "EN": "<div class=\\"cell-rich\\" data-col=\\"question_text\\"><div data-col=\\"question_text\\"><p>You are project manager in a global project with a team consisting of people from various countries. How can you prevent misunderstandings due to cross-cultural differences?</p></div></div>"\n                },\n                "question_image": null,\n                "options": [\n                    {\n                        "id": "A",\n                        "text": {\n                            "EN": "Use all communication methods available that are suitable for the team that helps team members work cohesively. Cultural and individual diversity may help project teams solve unforeseen problems"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "B",\n                        "text": {\n                            "EN": "When forming a project team, keep in mind that some cultures have your values, and some do not. Consequently, avoid choosing members from countries with cultures not similar to your own"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "C",\n                        "text": {\n                            "EN": "Cultural dilemmas can prevent any project from being successful. They should ensure that these issues cannot disrupt project work, and your efforts should concentrate on communication that can help reach that goal"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "D",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "E",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "F",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "G",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "H",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    },\n                    {\n                        "id": "I",\n                        "text": {\n                            "EN": "NA"\n                        },\n                        "image_url": null\n                    }\n                ],\n                "correct_answer_id": "A",\n                "marks_per_question": 1,\n                "minus_marks_per_question": 0.5,\n                "explanation_in_english": "<div class=\\"cell-rich\\" data-col=\\"explanation\\"><p>Use all suitable communication methods to ensure team cohesion. Embrace both verbal and nonverbal communication and recognize cultural and individual diversity to enhance problem-solving and reduce misunderstandings.</p></div>",\n                "explanation_image": null,\n                "active": true,\n                "is_error": false,\n                "train": [],\n                "flip_back": [],\n                "flip_front": [],\n                "error": [],\n                "__v": 0,\n                "createdAt": "2026-06-15T09:21:19.363Z",\n                "updatedAt": "2026-06-15T09:21:19.363Z",\n                "id": "6a2fc40fc40ebece41165d62"\n            }\n        ],\n        "totalDocs": 115,\n        "limit": 10,\n        "totalPages": 12,\n        "page": 3,\n        "pagingCounter": 21,\n        "hasPrevPage": true,\n        "hasNextPage": true,\n        "prevPage": 2,\n        "nextPage": 4\n    },\n    "myvalue": {\n        "page": "3"\n    },\n    "error": [],\n    "msg": []\n}'))
